 c.setStrokeColor(colors.HexColor('#C5DACE'));c.line(42,44,553,44);c.setFont('Helvetica',8);c.setFillColor(colors.HexColor('#5F776A'));c.drawString(42,30,'DDHI Smart Pharmacy | Server Control 0.2.0 | 13 November 2026');c.drawRightString(553,30,str(d.page))
